/**
 * Acceptance gate for the BLE protocol port.
 *
 * `golden_vectors.json` is GENERATED by `tools/gen_golden.py` from the real,
 * hardware-proven Python modules (`cardi_ble.py`, `symphony_modes.py`). Every
 * vector below must come out byte-identical from the JavaScript port. If one
 * fails, the JS is wrong - never edit the JSON by hand.
 */

import { describe, expect, it } from 'vitest';

import vectors from './golden_vectors.json';
import {
  asciiFrame,
  bytesToHex,
  hexToBytes,
  hexToRgb,
  rgbToHex,
  toDataView,
} from '../protocol/hex.js';
import {
  CHAR_FFE1,
  CHAR_FFE2,
  SERVICE_UUID,
  ZONE,
  classifyName,
  payloadBrightness,
  payloadPower,
  payloadRgb,
  payloadRgbMode,
  payloadScene,
  payloadSpeed,
  uiSpeedToFirmware,
  writeUuidFor,
} from '../protocol/frames.js';
import {
  CATEGORIES,
  DAZZLE_NAMES,
  MUSIC_NAMES,
  SHADOW_NAMES,
  namesFor,
  payloadSymphonyA,
} from '../protocol/symphony.js';
import { FAMILIES, RGB_ANIMATIONS, ZONES, modesFor } from '../protocol/catalog.js';

const label = (parts) => parts.join(' ');

describe('golden vectors: coverage', () => {
  it('carries the full generated set', () => {
    expect(vectors.power).toHaveLength(4);
    expect(vectors.rgb).toHaveLength(60);
    expect(vectors.brightness).toHaveLength(60);
    expect(vectors.rgbMode).toHaveLength(62);
    expect(vectors.symphony).toHaveLength(168);
    const total = Object.values(vectors).reduce((n, list) => n + list.length, 0);
    expect(total).toBe(354);
  });

  it('includes the mandated colour extremes on every zone', () => {
    for (const zone of [1, 2, 3]) {
      for (const color of ['000000', 'ffffff']) {
        const hit = vectors.rgb.find(
          (v) => v.args.hw === 'A' && v.args.zone === zone && v.args.color === color,
        );
        expect(hit, `A z${zone} ${color}`).toBeTruthy();
      }
    }
  });
});

describe('payloadPower', () => {
  for (const v of vectors.power) {
    it(label(['hw', v.args.hw, v.args.on ? 'on' : 'off']), () => {
      expect(bytesToHex(payloadPower(v.args.hw, v.args.on))).toBe(v.hex);
    });
  }
});

describe('payloadRgb', () => {
  for (const v of vectors.rgb) {
    const { hw, r, g, b, zone, color } = v.args;
    it(label(['hw', hw, 'zone', String(zone), color]), () => {
      expect(bytesToHex(payloadRgb(hw, r, g, b, zone))).toBe(v.hex);
    });
  }

  it('defaults to zone 3 (all)', () => {
    const expected = vectors.rgb.find(
      (v) => v.args.hw === 'A' && v.args.zone === 3 && v.args.color === 'ff8a3d',
    );
    expect(bytesToHex(payloadRgb('A', 0xff, 0x8a, 0x3d))).toBe(expected.hex);
  });

  it('rejects a zone the controller does not have', () => {
    expect(() => payloadRgb('A', 255, 0, 0, 4)).toThrow(/Unknown zone/);
    expect(() => payloadRgb('B', 255, 0, 0, 0)).toThrow(/Unknown zone/);
  });
});

describe('payloadBrightness', () => {
  for (const v of vectors.brightness) {
    const { hw, level, zone } = v.args;
    it(label(['hw', hw, 'zone', String(zone), 'level', String(level)]), () => {
      expect(bytesToHex(payloadBrightness(hw, level, zone))).toBe(v.hex);
    });
  }

  it('clamps to the firmware 0..9 scale', () => {
    const zero = vectors.brightness.find(
      (v) => v.args.hw === 'A' && v.args.zone === 3 && v.args.level === 0,
    );
    const nine = vectors.brightness.find(
      (v) => v.args.hw === 'A' && v.args.zone === 3 && v.args.level === 9,
    );
    expect(bytesToHex(payloadBrightness('A', -7, 3))).toBe(zero.hex);
    expect(bytesToHex(payloadBrightness('A', 100, 3))).toBe(nine.hex);
    expect(bytesToHex(payloadBrightness('A', 5.9, 3))).toBe(
      vectors.brightness.find(
        (v) => v.args.hw === 'A' && v.args.zone === 3 && v.args.level === 5,
      ).hex,
    );
  });
});

describe('payloadRgbMode', () => {
  for (const v of vectors.rgbMode) {
    const { hw, select, name } = v.args;
    it(label(['hw', hw, String(select), name]), () => {
      expect(bytesToHex(payloadRgbMode(hw, select))).toBe(v.hex);
    });
  }

  it('clamps select to 1..31', () => {
    const first = vectors.rgbMode.find((v) => v.args.hw === 'A' && v.args.select === 1);
    const last = vectors.rgbMode.find((v) => v.args.hw === 'A' && v.args.select === 31);
    expect(bytesToHex(payloadRgbMode('A', 0))).toBe(first.hex);
    expect(bytesToHex(payloadRgbMode('A', 99))).toBe(last.hex);
  });
});

describe('payloadSymphonyA', () => {
  for (const v of vectors.symphony) {
    const { kind, mode, name } = v.args;
    it(label([kind, String(mode), name]), () => {
      expect(bytesToHex(payloadSymphonyA(kind, mode))).toBe(v.hex);
    });
  }

  it('rejects out-of-range modes', () => {
    expect(() => payloadSymphonyA('dazzle', 64)).toThrow('dazzle mode 1-63');
    expect(() => payloadSymphonyA('music', 43)).toThrow('music mode 1-42');
    expect(() => payloadSymphonyA('shadow', 64)).toThrow('shadow mode 1-63');
    expect(() => payloadSymphonyA('nope', 1)).toThrow('nope');
  });
});

describe('mode name tables match the Python source', () => {
  it('RGB_ANIMATIONS lines up with every rgbMode vector', () => {
    expect(RGB_ANIMATIONS).toHaveLength(31);
    for (const v of vectors.rgbMode) {
      const entry = RGB_ANIMATIONS.find((item) => item.index === v.args.select);
      expect(entry.name).toBe(v.args.name);
    }
  });

  it('Symphony tables line up with every symphony vector', () => {
    expect(DAZZLE_NAMES).toHaveLength(63);
    expect(MUSIC_NAMES).toHaveLength(42);
    expect(SHADOW_NAMES).toHaveLength(63);
    for (const v of vectors.symphony) {
      expect(namesFor(v.args.kind)[v.args.mode - 1]).toEqual({
        index: v.args.mode,
        name: v.args.name,
      });
    }
  });
});

describe('payloadScene', () => {
  const A = {
    rainbow: '3C 30 34 30 30 30 30 3E',
    flash: '3C 30 34 30 30 30 63 3E',
    breathe: '3C 30 34 30 30 31 38 3E',
    music: '3C 30 34 30 35 30 31 3E',
  };
  const B = {
    rainbow: '3B 34 34 34 34 07 B3',
    flash: '3B 34 34 34 34 21 B3',
    breathe: '3B 34 34 34 34 18 B3',
    music: '3B 34 34 34 34 0B B3',
  };

  for (const scene of Object.keys(A)) {
    it(`A ${scene}`, () => expect(bytesToHex(payloadScene('A', scene))).toBe(A[scene]));
    it(`B ${scene}`, () => expect(bytesToHex(payloadScene('B', scene))).toBe(B[scene]));
  }

  it('rejects an unknown scene', () => {
    expect(() => payloadScene('A', 'disco')).toThrow('Unknown scene: disco');
    expect(() => payloadScene('B', 'disco')).toThrow('Unknown scene: disco');
  });
});

describe('uiSpeedToFirmware', () => {
  it('maps 1 to the slowest firmware value and 6 to the fastest', () => {
    expect(uiSpeedToFirmware(1)).toBe(0);
    expect(uiSpeedToFirmware(2)).toBe(2);
    expect(uiSpeedToFirmware(3)).toBe(4);
    expect(uiSpeedToFirmware(4)).toBe(6);
    expect(uiSpeedToFirmware(5)).toBe(8);
    expect(uiSpeedToFirmware(6)).toBe(10);
  });
});

describe('payloadSpeed', () => {
  it('encodes Type A RGB speed with the +30 ASCII trick and the level-10 substitute', () => {
    expect(bytesToHex(payloadSpeed('A', 0, 'rgb'))).toBe('3C 33 65 30 30 3E');
    expect(bytesToHex(payloadSpeed('A', 5, 'rgb'))).toBe('3C 33 65 30 35 3E');
    expect(bytesToHex(payloadSpeed('A', 10, 'rgb'))).toBe('3C 33 65 30 61 3E');
  });

  it('encodes Type A Symphony speed on the separate 0b0 command', () => {
    expect(bytesToHex(payloadSpeed('A', 5, 'symphony'))).toBe('3C 30 62 30 35 3E');
    expect(bytesToHex(payloadSpeed('A', 10, 'symphony'))).toBe('3C 30 62 30 61 3E');
  });

  it('encodes Type B as a single global 0x38 frame', () => {
    expect(bytesToHex(payloadSpeed('B', 5))).toBe('3B 38 F3 00 00 05 B3');
    expect(bytesToHex(payloadSpeed('B', 10))).toBe('3B 38 F3 00 00 0A B3');
  });

  it('clamps to 0..10', () => {
    expect(bytesToHex(payloadSpeed('A', -3, 'rgb'))).toBe(bytesToHex(payloadSpeed('A', 0, 'rgb')));
    expect(bytesToHex(payloadSpeed('A', 99, 'rgb'))).toBe(bytesToHex(payloadSpeed('A', 10, 'rgb')));
  });
});

describe('device identity', () => {
  it('classifies advertised names like classify_name()', () => {
    // Verified against cardi_ble.classify_name for each of these exact strings.
    expect(classifyName('ATW-FWD-AAA6')).toBe('A'); // the pinned Hycross box
    expect(classifyName('atw-fwd')).toBe('A');
    expect(classifyName('VE-CD-01')).toBe('A'); // 'VE-CD' is Type A, not 'CD-AMB'
    expect(classifyName('CD-AMB')).toBe('B');
    expect(classifyName('CD-AMB-01')).toBe('B');
    expect(classifyName('Random Speaker')).toBeNull();
    expect(classifyName('')).toBeNull();
    expect(classifyName(null)).toBeNull();
    expect(classifyName(undefined)).toBeNull();
  });

  it('picks the write characteristic like write_uuid_for()', () => {
    expect(writeUuidFor('B')).toBe(CHAR_FFE1);
    expect(writeUuidFor('A')).toBe(CHAR_FFE2);
    expect(writeUuidFor(null)).toBe(CHAR_FFE2);
    expect(SERVICE_UUID).toBe('0000ffe0-0000-1000-8000-00805f9b34fb');
  });
});

describe('hex helpers', () => {
  it('round-trips bytes through hex', () => {
    const bytes = hexToBytes('3C 30 37 30 31 3E');
    expect(Array.from(bytes)).toEqual([0x3c, 0x30, 0x37, 0x30, 0x31, 0x3e]);
    expect(bytesToHex(bytes)).toBe('3C 30 37 30 31 3E');
    expect(bytesToHex(bytes, '')).toBe('3C303730313E');
  });

  it('rejects malformed hex', () => {
    expect(() => hexToBytes('3C3')).toThrow(/odd-length/);
    expect(() => hexToBytes('3CZZ')).toThrow(/invalid hex/);
  });

  it('wraps ASCII in the Type A frame', () => {
    expect(bytesToHex(asciiFrame('0701'))).toBe('3C 30 37 30 31 3E');
  });

  it('exposes the same memory as a DataView', () => {
    const bytes = hexToBytes('3B33 03FF 0000 B3');
    const view = toDataView(bytes);
    expect(view.byteLength).toBe(7);
    expect(view.getUint8(0)).toBe(0x3b);
    expect(view.getUint8(6)).toBe(0xb3);
  });

  it('converts between #rrggbb and channels', () => {
    expect(hexToRgb('#FF8A3D')).toEqual({ r: 255, g: 138, b: 61 });
    expect(hexToRgb('0a0b0e')).toEqual({ r: 10, g: 11, b: 14 });
    expect(hexToRgb('#fff')).toEqual({ r: 255, g: 255, b: 255 });
    expect(rgbToHex(255, 138, 61)).toBe('#ff8a3d');
    expect(rgbToHex(0, 0, 0)).toBe('#000000');
    expect(rgbToHex(300, -20, 14)).toBe('#ff000e');
    expect(() => hexToRgb('nope')).toThrow(/expected #rrggbb/);
  });
});

describe('catalog reflects hardware truth', () => {
  it('exposes exactly three zones totalling 19 pieces', () => {
    expect(ZONES.map((z) => z.id)).toEqual([3, 1, 2]);
    expect(ZONE).toEqual({ FRONT: 1, REAR: 2, ALL: 3 });
    const byId = Object.fromEntries(ZONES.map((z) => [z.id, z]));
    expect(byId[1].pieces).toBe(12);
    expect(byId[2].pieces).toBe(7);
    expect(byId[3].pieces).toBe(19);
    expect(byId[1].pieces + byId[2].pieces).toBe(byId[3].pieces);
  });

  it('modesFor returns a contiguous 1-based list for every family', () => {
    expect(FAMILIES.map((f) => f.key)).toEqual(['rgb', 'dazzle', 'music', 'shadow']);
    for (const family of FAMILIES) {
      const modes = modesFor(family.key);
      expect(modes).toHaveLength(family.count);
      expect(modes.map((m) => m.index)).toEqual(
        Array.from({ length: family.count }, (_, i) => i + 1),
      );
      for (const mode of modes) expect(mode.name.length).toBeGreaterThan(0);
    }
    expect(Object.keys(CATEGORIES)).toEqual(['dazzle', 'music', 'shadow']);
  });
});
